import json
leg = {'hip': 0.1, 'thigh': 0.8, 'calf': -1.5}
joints = {}
for j in app.actions.run('robot.joints')['joints']:
    side, part = j['name'].split('/')[-1].split('_')[:2]
    q = leg[part] * (-1.0 if part == 'hip' and side[1] == 'R' else 1.0)
    joints[j['name']] = q + (0.2 if part == 'thigh' and side[0] == 'R' else 0.0)
assert len(joints) == 12, joints
json.dump({'poses': [{'name': 'stand', 'joints': joints}]}, open(r'${out}/stand.json', 'w'))

p, q = ${tp1}, ${tp0}
assert p['page'] == 'task' and p['problems'] == 0 and p['changed'] == 0, p
assert p['config_version'] > q['config_version'], (p, q)

s = ${s0}
print('BASE', {k: s[k] for k in ('state', 'epoch', 'fps', 'reward', 'best_reward', 'checkpoints')})
assert s['state'] == 'finished' and s['epoch'] == 6, s

for page in ('task', 'runs', 'dashboard', 'checkpoints'):
    app.actions.run('train.panel', page=page)
    for _ in range(3):
        app.update(True)
